const input = $json.body ? $json : { body: $json, headers: {} };
const body = input.body || {};
const headers = input.headers || {};
const auth = headers.authorization || headers.Authorization || '';
const token = String(auth).replace(/^Bearer\s+/i, '');
const mcpUrl = body.mcpUrl || $env.RUNNING_API_MCP_URL || '';
if (!token) throw new Error('Falta Authorization: Bearer <jwt> en el webhook');
if (!body.requestId || !body.date) throw new Error('Faltan requestId o date en el body');
if (!mcpUrl) throw new Error('Falta mcpUrl en el body o RUNNING_API_MCP_URL');
const separator = mcpUrl.includes('?') ? '&' : '?';
const mcpEndpoint = mcpUrl + separator + 'access_token=' + encodeURIComponent(token);
return [{ json: { token, mcpUrl, mcpEndpoint, requestId: body.requestId, date: body.date, replace: body.replace === true || body.replace === 'true' } }];

const raw = typeof $json.output === 'string' ? $json.output : JSON.stringify($json.output ?? '');
let text = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
const start = text.indexOf('{');
const end = text.lastIndexOf('}');
if (start >= 0 && end > start) text = text.slice(start, end + 1);
if (!text) throw new Error('El agente no devolvió una recomendación JSON');
const recommendation = JSON.parse(text);
const p = $('Preparar llamadas MCP').item.json;
return [{ json: { ...p, recommendation, recommendationJson: JSON.stringify(recommendation) } }];

const raw = $json?.result?.content?.[0]?.text;
let result = {};
try { result = raw ? JSON.parse(raw) : {}; } catch (e) { result = { ok: false, message: 'Respuesta MCP no es JSON: ' + raw }; }
const p = $('Preparar llamadas MCP').item.json;
return [{ json: { ...p, saveResult: result, saved: result.ok === true, recommendation: result.recommendation || null, failError: result.ok === true ? null : (result.message || JSON.stringify(result)) } }];

const r = $json.recommendation;
if (!r) throw new Error('No hay recomendación guardada para el mensaje');
const w = r.workout || {};
const lines = ['🏃 ' + r.date + ' · ' + (w.type || '') + ' — ' + (w.title || '')];
if (r.summary) lines.push(r.summary);
if (w.targetDistanceMeters) lines.push('Distancia: ' + (w.targetDistanceMeters / 1000).toFixed(1) + ' km');
if (w.targetDurationSeconds) lines.push('Duración: ' + Math.round(w.targetDurationSeconds / 60) + ' min');
if (w.targetPaceMinPerKm) lines.push('Ritmo: ' + w.targetPaceMinPerKm + ' min/km');
if (w.targetHrZone) lines.push('Zona FC: Z' + w.targetHrZone);
if (w.mainSet) lines.push('Bloque: ' + w.mainSet);
if (r.analysis) lines.push('', '📊 ' + r.analysis);
if (r.coachNotes) lines.push('💡 ' + r.coachNotes);
lines.push('', 'ID: ' + r.recommendationId);
return [{ json: { telegramText: lines.join('\n') } }];

const p = $('Preparar llamadas MCP').item.json;
const error = $json.failError || $json.saveResult?.message || $json.error?.message || $json.message || 'Error generando la recomendación';
return [{ json: { ...p, failError: String(error) } }];

const p = $('Preparar fallo').item.json;
const text = '⚠️ No se pudo generar la recomendación diaria (' + p.date + ').\n' + p.failError + '\nrequestId: ' + p.requestId;
return [{ json: { telegramText: text } }];
